    getCancelAction:function(){
        return{
            text: 'Cancelar Solicitação',
            scope: this,
            iconCls: true,
            icon: '/' + global.Context + '/static/rh/images/denied.png',
            handler: function () {
                if (this.getSelectionModel().getSelected()) {
                    var cod = this.getSelectionModel().getSelected().id
                    var type = this.getSelectionModel().getSelected().data.type_of_request
                    Ext.Msg.show({
                        title:"Cancelar Solicitação",
                        icon: Ext.Msg.QUESTION,
                        buttons: Ext.Msg.YESNO,
                        msg: 'Deseja mesmo cancelar a solicitação de '+type+" Código: "+cod+' ?',
                        scope: this,
            
                        fn: function (btn) {
                            if (btn == 'no') return;
                            var params = {
                                pk: cod,
                            };
                            this._cancel(params);
                        }
                    });
                   
                } else {
                    Ext.Msg.show({
                        title: "Cancelar",
                        msg: "Selecione uma Solicitação!",
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                    });
                }
            }
        }

    },

