    createItem: function (classDef,type_usufruct,obj) {
        this.setParam('type_of_usufruct_id', type_usufruct);
        if (Object.keys(obj).length > 0)
            this.setParam('month',obj.month)
            this.setParam('year',obj.year)
            this.setParam('current_work_plan_start_date',obj.current_work_plan_start_date)
            this.setParam('current_work_plan_end_date',obj.current_work_plan_end_date)
            this.setParam('plan_work_presential',obj.plan_work_presential)
            this.setParam('plan_work_id',obj.plan_work_id)
            this.setParam('daily_workload',obj.daily_workload)
            this.setParam('solicitation',true)
            this.setParam('pk',obj.pk)
        var swapRestWindow = this.restWindow;
        this.restWindow = classDef;
        rh.pvf.portalrequest.Grid.superclass.createItem.call(this);
        this.restWindow = swapRestWindow;
    },

    defaultClickFunction: function() {
        if(this.getSelectionModel().getSelected()) this.detail();
    },

    detail: function (record) {
        if (!this.getSelectionModel().getSelected()) {
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Selecione um item!'
            });
        } else {
            var selected = this.getSelectionModel().getSelected();
            request_type = selected.get('request_type')
            Ext._create(selected.data.path_datail_window, {
                data: selected.data,
                grid:this,
                responsible:this.getParams().responsible,
                action: 'update',
                title: 'Detalhes da Solicitação',
            }).show();
        }

    },

